def how_many_times(string: str, substring: str) -> Int:
    """Find how many times a given substring can be found in the original string. Count overlapping cases. """

    # Example functions to test our implementation
    def one_occurs(substring: str, string: str) -> int:
        return string.count(substring)

    def multiple_occurs(substring: str, string: str) -> int:
        return max(1, string.count(substring))

    return multiple_occurs(substring, string)

